// Breaks caught: persistence/ownership, overbooking, duplicate claim, unsafe bind/release/retry.
use agentranch::{config::{Actor,NodeSpec},core::store::{Store,ExitProof}};
use tempfile::TempDir;
fn nodes()->Vec<NodeSpec>{vec![NodeSpec{id:"B".into(),address:"local-b/runner".into(),key_hex:"07".repeat(32),slots:1,admitted:true,healthy:true,draining:false,templates:vec!["sum-native-v1".into(),"control-native-v1".into()]}]}
fn owner()->Actor{Actor::Local("tester".into())}
fn setup()->(TempDir,Store){let tmp=tempfile::tempdir().unwrap();let db=Store::open(&tmp.path().join("native.db"),"native-test",&nodes()).unwrap();(tmp,db)}
#[test]
fn persisted_dispatch_has_exact_owner_and_does_not_import_other_identity(){let(tmp,mut s)=setup();let r=s.dispatch(&owner(),"sum-native-v1",100).unwrap();drop(s);let s=Store::open(&tmp.path().join("native.db"),"native-test",&nodes()).unwrap();assert_eq!(s.owned(&owner(),&r.id).unwrap().status,"queued");assert!(s.owned(&Actor::AoSession("tester".into()),&r.id).is_err());assert!(s.owned(&Actor::Local("other".into()),&r.id).is_err());}
#[test]
fn fifo_reserves_exact_one_slot_and_persists_start_outbox(){let(_tmp,mut s)=setup();let one=s.dispatch(&owner(),"sum-native-v1",100).unwrap();let two=s.dispatch(&owner(),"sum-native-v1",101).unwrap();let a=s.assign_next(102).unwrap().unwrap();assert_eq!(a.run_id,one.id);assert_eq!(a.node_id,"B");assert_eq!(a.address,"local-b/runner");assert_eq!(s.outbox_count().unwrap(),1);assert!(s.assign_next(103).unwrap().is_none());assert_eq!(s.run(&two.id).unwrap().status,"queued");}
#[test]
fn changed_deployment_key_or_address_is_refused_on_reopen(){let(tmp,s)=setup();drop(s);let path=tmp.path().join("native.db");assert!(Store::open(&path,"other",&nodes()).is_err());for field in 0..2{let mut n=nodes();if field==0{n[0].key_hex="08".repeat(32)}else{n[0].address="foreign/runner".into()};assert!(Store::open(&path,"native-test",&n).is_err());}Store::open(&path,"native-test",&nodes()).unwrap();}
#[test]
fn two_connections_claim_once_and_late_bind_preserves_cancel(){let(tmp,mut s)=setup();let r=s.dispatch(&owner(),"control-native-v1",100).unwrap();s.assign_next(101).unwrap();assert!(s.claim(&r.id,1,&r.epoch).unwrap());let mut other=Store::open(&tmp.path().join("native.db"),"native-test",&nodes()).unwrap();assert!(!other.claim(&r.id,1,&r.epoch).unwrap());other.cancel(&owner(),&r.id).unwrap();s.bind(&r.id,1,&r.epoch,"worker-1").unwrap();let r=s.run(&r.id).unwrap();assert_eq!(r.status,"cancel_pending");assert_eq!(r.session.as_deref(),Some("worker-1"));assert!(r.detail.get("cancel_requested").is_some());assert!(s.bind(&r.id,1,"wrong-epoch","other").is_err());assert!(s.bind(&r.id,1,&r.epoch,"other").is_err());}
#[test]
fn unknown_claimed_session_cannot_be_false_not_started_or_retried(){let(_tmp,mut s)=setup();let r=s.dispatch(&owner(),"control-native-v1",100).unwrap();s.assign_next(101).unwrap();s.claim(&r.id,1,&r.epoch).unwrap();s.cancel(&owner(),&r.id).unwrap();let proof=ExitProof{run_id:r.id.clone(),attempt:1,epoch:r.epoch.clone(),session:None,empty:true,observer_alive:true,not_started:true,owner_evidence:None};assert!(!s.release(&proof).unwrap());assert!(s.retry(&owner(),&r.id,1).is_err());assert!(!s.assignment(&r.id,1).unwrap().unwrap().released);}
#[test]
fn matching_minimal_exit_retains_current_assignment_and_does_not_start_successor(){let(_tmp,mut s)=setup();let r=s.dispatch(&owner(),"control-native-v1",100).unwrap();let successor=s.dispatch(&owner(),"sum-native-v1",100).unwrap();s.assign_next(101).unwrap();s.claim(&r.id,1,&r.epoch).unwrap();s.bind(&r.id,1,&r.epoch,"worker-1").unwrap();s.cancel(&owner(),&r.id).unwrap();let mut proof=ExitProof{run_id:r.id.clone(),attempt:1,epoch:r.epoch.clone(),session:Some("wrong".into()),empty:true,observer_alive:true,not_started:false,owner_evidence:None};assert!(!s.release(&proof).unwrap());proof.session=Some("worker-1".into());proof.observer_alive=false;assert!(!s.release(&proof).unwrap());proof.observer_alive=true;assert!(!s.release(&proof).unwrap());assert_eq!(s.run(&r.id).unwrap().status,"cancel_pending");assert!(s.assign_next(102).unwrap().is_none());assert!(!s.assignment(&r.id,1).unwrap().unwrap().released);assert_eq!(s.run(&successor.id).unwrap().status,"queued");}
#[test]
fn unassigned_cancel_is_safe_and_retry_uses_a_new_attempt(){let(_tmp,mut s)=setup();let r=s.dispatch(&owner(),"sum-native-v1",100).unwrap();assert_eq!(s.cancel(&owner(),&r.id).unwrap().status,"cancelled");let retry=s.retry(&owner(),&r.id,1).unwrap();assert_eq!(retry.attempt,2);assert_ne!(retry.epoch,r.epoch);assert_eq!(retry.status,"queued");assert!(s.retry(&owner(),&r.id,1).is_err());}
#[test]
fn unknown_template_and_model_supplied_paths_are_refused(){let(_tmp,mut s)=setup();assert!(s.dispatch(&owner(),"arbitrary-shell",100).is_err());assert!(s.dispatch(&owner(),"../sum-native-v1",100).is_err());}
